import{z as d,x as i,o as t,c as A,q as o,j as s,D as a,d as r,s as n,S as B,b as l}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"Bw-tree","description":"","frontmatter":{"title":"Bw-tree","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/bw-tree.md","filePath":"cs/bw-tree.md","lastUpdated":1791413859000}'),p={name:"cs/bw-tree.md"};function c(C,e,S,h,m,D){const E=i("Mermaid");return t(),A("div",null,[e[2]||(e[2]=o('<h1 id="bw-tree" tabindex="-1">Bw-tree <a class="header-anchor" href="#bw-tree" aria-label="Permalink to &quot;Bw-tree&quot;">​</a></h1><div class="epigraph"><p>逻辑页是映射表里的指针：原地改换成 delta 记录链，CAS 安装新地址；结构修改也走无闩路径。</p><footer>—— 据 Levandoski, Lomet and Sengupta, The Bw-Tree, ICDE 2013；B-link 对照</footer></div><p><a href="/cs/latch-crabbing">上一课</a>在页闩上蟹行。本课不持写闩走满节点。缺口是主存优化索引：多核上 latch 仍是缓存行争用。Bw-tree 把「页」变成映射表（page id → 地址），更新用单字 CAS 挂 delta，读方沿着 delta 链看到最新逻辑页。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>传统 B+：改槽要写闩，叶热点（递增键）把核排队。Bw-tree：插入是分配 delta 记录（键+载荷），CAS 把映射表从旧页地址改到「delta→旧页」。失败则重试。缺口是<strong>无闩并不无同步</strong>，同步在 CAS 与 epoch 回收。</p><p><span class="marginnote">术语翻译：CAS（比较并交换）是一条原子指令——内存值仍等于我上次看到的旧值才允许换成新值，否则失败重试；Bw-tree 用它替代写闩，同步点从「排队拿闩」变成「抢着安装一次」。</span></p><p>链太长则 consolidate：把 delta 与基页合成新基页，再 CAS 安装。分裂/合并是安装新页 id 并改父，用 SMO 协议保证读者看到一致。闪存/持久化变体另说；原论文面向主存+日志。</p><p><span class="marginnote">Levandoski, Lomet, Sengupta, ICDE 2013，微软 Hekaton 相关。ART 下一课是另一主存索引族（基数树）。本课不把 Bw 当磁盘 B+ 的替代教条。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>查找：映射表取地址，沿 delta 链+基页二分或扫描。范围：逻辑叶有序，链上有插入删除。GC：epoch 或类似，确保无读者还在旧地址上才回收。崩溃：映射表与页要进 WAL 或检查点，比纯内存结构重。</p><p><span class="marginnote">直觉类比：delta 链像贴在文件前面的「修订便签」——正文不动，改动一条条往上贴；读者从最新便签往回拼出当前版本，consolidate 就是把便签誊清成新正文，再一次 CAS 换掉封面地址。</span></p><p>与缓冲池：逻辑页可能不在固定帧模型里；主存库常自己分配。磁盘库用 Bw 要重新设计落盘，本课点名边界。</p>',12)),(t(),s(B,null,{default:a(()=>[n(E,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20PID%5B%22page%20id%22%5D%20--%3E%20MAP%5B%22%E6%98%A0%E5%B0%84%E8%A1%A8%20CAS%22%5D%0A%20%20MAP%20--%3E%20D%5B%22delta%20%E8%AE%B0%E5%BD%95%22%5D%0A%20%20D%20--%3E%20BASE%5B%22%E5%9F%BA%E9%A1%B5%22%5D%0A%20%20D%20--%3E%20CONS%5B%22%E9%93%BE%E9%95%BF%E5%88%99%E5%90%88%E5%B9%B6%E6%96%B0%E5%9F%BA%E9%A1%B5%22%5D%0A"})]),fallback:a(()=>[...e[0]||(e[0]=[r(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=l("h2",{id:"机制",tabindex:"-1"},[r("机制 "),l("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),e[4]||(e[4]=l("p",null,"正确性：读者看到的链是某次 CAS 前缀，不会撕裂槽。隔离仍要事务层（锁或 MVCC 版本在载荷里）。Bw 只替换页闩这一层。",-1)),(t(),s(B,null,{default:a(()=>[n(E,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20UPD%5B%22%E6%8F%92%E5%85%A5%20k%3Dv%22%5D%20--%3E%20AL%5B%22%E5%88%86%E9%85%8D%20delta%20%E8%AE%B0%E5%BD%95%22%5D%0A%20%20AL%20--%3E%20CAS%5B%22CAS%3A%20%E6%98%A0%E5%B0%84%E8%A1%A8%E6%97%A7%E5%9C%B0%E5%9D%80%E6%94%B9%E6%88%90%20delta%20%E9%93%BE%E5%A4%B4%22%5D%0A%20%20CAS%20--%3E%7C%22%E6%88%90%E5%8A%9F%22%7C%20VIS%5B%22%E8%AF%BB%E8%80%85%E6%8B%BC%E5%87%BA%E6%96%B0%E9%80%BB%E8%BE%91%E9%A1%B5%22%5D%0A%20%20CAS%20--%3E%7C%22%E5%A4%B1%E8%B4%A5%22%7C%20RE%5B%22%E9%87%8D%E8%AF%BB%E6%98%A0%E5%B0%84%E8%A1%A8%E5%86%8D%E8%AF%95%22%5D%0A%20%20RE%20--%3E%20AL%0A%20%20LONG%5B%22%E9%93%BE%E8%BF%87%E9%95%BF%22%5D%20--%3E%20CONS%5B%22%E5%90%88%E5%B9%B6%E6%88%90%E6%96%B0%E5%9F%BA%E9%A1%B5%E5%86%8D%20CAS%22%5D%0A"})]),fallback:a(()=>[...e[1]||(e[1]=[r(" Loading... ",-1)])]),_:1})),e[5]||(e[5]=o('<p><span class="marginnote">数字实例：某逻辑页积了 8 条 delta 时，一次点查要先读映射表、再顺 8 次指针才到基页；consolidate 后回到「映射表加基页」2 次跳转——用一次重写把持续的读放大买回来。</span></p><p>与 LRU-K 无关若页不进经典池。混合引擎可能叶在 Bw、溢出在磁盘 B+——实现复杂性高。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不讲 ART 的 Node4/16/48/256。也不把无锁跳表当 Bw。学习索引更后。</p><p>后课默认：高并发主存点查可用映射+delta 减少写闩。ART 在数据库：字节序范围扫描的自适应基数树，常作主存主索引。</p><p>无闩索引把争用从锁管理器挪到 CAS 与回收，不取消事务语义。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Bw-tree 用映射表与 delta CAS 更新逻辑页。</li><li>链合并与 SMO 仍要协议；GC 用 epoch。</li><li>ART 在数据库下一课：有序主存索引的另一形状。</li><li>出处：Levandoski, Lomet, Sengupta, ICDE 2013；B-link 对照。</li></ul>',8))])}const b=d(p,[["render",c]]);export{_ as __pageData,b as default};
